/**
 * Embedded TR-DOS ROM (16 KiB) for Beta 128. See third_party/spectrum/README.md.
 * Generated — do not edit by hand.
 */
export const SPECTRUM_TRDOS_ROM_BYTES = 16384;

export function loadSpectrumTrdosRom(): Uint8Array {
  const b64 = "";
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
